// ── Wayland listeners ────────────────────────────────────────────────────────

static void registry_handler(void* data, wl_registry* registry, uint32_t id,
                             const char* interface, uint32_t version) {
    auto* window = static_cast<WaylandWindow*>(data);

    if (strcmp(interface, "wl_compositor") == 0) {
        window->compositor_ = static_cast<wl_compositor*>(
            wl_registry_bind(registry, id, &wl_compositor_interface, 1));
    } else if (strcmp(interface, "xdg_wm_base") == 0) {
        window->xdgBase_ = static_cast<xdg_wm_base*>(
            wl_registry_bind(registry, id, &xdg_wm_base_interface, 1));
    } else if (strcmp(interface, "wl_shm") == 0) {
        window->shm_ = static_cast<wl_shm*>(
            wl_registry_bind(registry, id, &wl_shm_interface, 1));
    } else if (strcmp(interface, "wl_seat") == 0) {
        window->seat_ = static_cast<wl_seat*>(
            wl_registry_bind(registry, id, &wl_seat_interface, 1));
    } else if (strcmp(interface, "wl_output") == 0) {
        window->output_ = static_cast<wl_output*>(
            wl_registry_bind(registry, id, &wl_output_interface, 1));
        if (window->output_) {
            wl_output_add_listener(window->output_, &output_listener, window);
        }
    } else if (strcmp(interface, "wl_data_device_manager") == 0) {
        window->dataDeviceManager_ = static_cast<wl_data_device_manager*>(
            wl_registry_bind(registry, id, &wl_data_device_manager_interface, 3));
    } else if (strcmp(interface, "zwp_text_input_manager_v3") == 0) {
        window->textInputManager_ = static_cast<zwp_text_input_manager_v3*>(
            wl_registry_bind(registry, id, &zwp_text_input_manager_v3_interface, 1));
    }
}

static void registry_remover(void* /*data*/, wl_registry* /*registry*/, uint32_t /*id*/) {
    // Ignore hot-unplug for now
}

static const wl_registry_listener registry_listener = {registry_handler, registry_remover};

