// ── Initialization helpers ───────────────────────────────────────────────────

void WaylandWindow::initSeat() {
    if (!seat_) return;

    uint32_t caps = wl_seat_get_capabilities(seat_);
    if (caps & WL_SEAT_CAPABILITY_POINTER) {
        pointer_ = wl_seat_get_pointer(seat_);
        if (pointer_) {
            wl_pointer_add_listener(pointer_, &pointer_listener, this);
        }
    }
    if (caps & WL_SEAT_CAPABILITY_KEYBOARD) {
        keyboard_ = wl_seat_get_keyboard(seat_);
        if (keyboard_) {
            wl_keyboard_add_listener(keyboard_, &keyboard_listener, this);
        }
    }
}

void WaylandWindow::initClipboard() {
    if (dataDeviceManager_ && seat_) {
        dataDevice_ = wl_data_device_manager_get_data_device(dataDeviceManager_, seat_);
        if (dataDevice_) {
            wl_data_device_add_listener(dataDevice_, &data_device_listener, this);
        }
    }
}

